WITH payload AS (SELECT $archive_payload$[{"id":"5e13b399-5ab6-5c80-a374-63ced18e2074","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -قطعة أرض -اإلفراغ الصوري -إفراغ الصك باسم مورث املدعى عليه صوري ا من أجل التقدمي على صندوق التنمية العقاري -إقرار املدعى عليهم بعدالة الشاهد -القضاء بشهادة رجل وامرأتن -ثبوت متلك املدعي لأرض موضع الدعوى -رفع املعاملة حملكمة الاستئناف لوجود قاصر ضمن املدعى عليهم.","document_number":"34207046","case_number":"3499874","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باألحساء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/6","year":"1434","subject":"بيع -عقار -قطعة أرض -اإلفراغ الصوري -إفراغ الصك باسم مورث املدعى عليه صوري ا من أجل التقدمي على صندوق التنمية العقاري -إقرار املدعى عليهم بعدالة الشاهد -القضاء بشهادة رجل وامرأتن -ثبوت متلك املدعي لأرض موضع الدعوى -رفع املعاملة حملكمة الاستئناف لوجود قاصر ضمن املدعى عليهم.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/5/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34207046 :‬‬\n                    ‫َر ْق ُم الدعوى‪3499874 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34255099‬تاريخه‪1434/6/28 :‬هـ‬\n\n\n‫بيــع ‪ -‬عقــار‪ -‬قطعــة أرض ‪ -‬اإلفــراغ الصــوري ‪ -‬إفــراغ الصــك باســم‬\n‫مــورث املدعــى عليــه صوري ـ ًا مــن أجــل التقــدمي علــى صنــدوق التنميــة‬\n‫العقــاري ‪ -‬إقــرار املدعــى عليهــم بعدالــة الشــاهد ‪ -‬القضــاء بشــهادة‬\n‫رجــل وامرأتــن ‪ -‬ثبــوت متلــك املدعــي لــأرض موضــع الدعــوى ‪ -‬رفــع‬\n    ‫املعاملــة حملكمــة االســتئناف لوجــود قاصــر ضمــن املدعــى عليهــم‪.‬‬\n\n\n\n\n‫قولــه تعالــى ( فــإن لــم يكونــا رجلــن فرجــل وامرأتــان ممــن ترضــون مــن‬\n                                                         ‫الشــهداء ) اآليــة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه اشــترى قطعــة أرض ( ذكــر وصفهــا ) وســلم الثمــن‬\n‫للبائــع وقبــل اإلفــراغ طلــب منــه أخــوه ( مــورث املدعــى عليهــم ) إفــراغ‬\n‫الصــك باســمه صوريـ ًا حتــى يتمكــن مــن التقــدمي علــى صنــدوق التنميــة‬\n‫العقــاري‪ ،‬مت اإلفــراغ باســم أخــي املدعــي (مــورث املدعــى عليهــم )‬\n‫تــويف أخــو املدعــي بعــد اإلفــراغ باســمه بســنتني تقريبـ ًا ولــم يســتفد مــن‬\n‫القــرض‪ ،‬طلــب املدعــي إلــزام ورثــة أخيــه بإعــادة إفــراغ األرض لــه‪ ،‬أقــر‬\n‫املدعــى عليهــم مبــا جــاء يف الدعــوى‪ ،‬حيــث إن مــن ضمــن الورثــة قاصــر ًا‬\n‫ا وامرأتــن‬    ‫لــذا طلــب مــن املدعــي البينــة علــى دعــواه‪ ،‬أحضــر رج ـ ً‬\n\n                                                                                      ‫‪230‬‬\n\f      ‫وشــهدوا بصحــة مــا جــاء يف الدعــوى‪ ،‬جــرى تعديــل الشــهود‪ ،‬جــرى‬\n      ‫االستفســار عــن ســريان مفعــول صــك األرض‪ ،‬كمــا جــرى الرجــوع إلــى‬\n      ‫صــك حصــر الورثــة وصــك الواليــة‪ ،‬صــدر احلكــم بثبــوت متلــك املدعــي‬\n      ‫لقطعــة األرض موضــع الدعــوى والتهميــش علــى صــك امللكيــة بذلــك‬\n      ‫بعــد تصديــق احلكــم مــن محكمــة االســتئناف‪ ،‬صــدق احلكــم مــن‬\n                                                          ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪...‬مســاعد رئيــس احملكمــة العامــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة مبحافظــة األحســاء برقــم ‪ 3499874‬وتاريــخ ‪1434/2/30‬ه ـ‬\n      ‫واملقيدة يف احملكمة برقم ‪ 34519564‬وتاريخ ‪1434/2/30‬هـ ويف يوم‬\n      ‫األحــد ‪1434/5/5‬ه ـ حضــر ‪...‬الســعودي بالســجل املدنــي رقــم ‪...‬وادعى‬\n      ‫علــى احلاضريــن معــه ‪ ...‬الســعودي بالســجل املدنــي رقــم ‪...‬و‪ ...‬الســعودية‬\n      ‫بالســجل املنــي رقــم ‪...‬أصيلــة عــن نفســها وبواليتهــا علــى ابنهــا القاصــر‬\n      ‫‪...‬الســعودي بالســجل املدنــي رقــم ‪ ...‬مبوجــب صــك الواليــة الصــادر مــن‬\n      ‫هــذه احملكمــة برقــم ‪ .....‬يف ‪ ..........‬جلــد‪ .....‬كــون املدعــى عليهــم ورثــة‬\n      ‫‪...‬مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪ .....‬يف‬\n      ‫ا يف حتريــر دعــواه إنــي اشــتريت مــن ‪...‬قطعــة‬      ‫‪ ..........‬ه ـ جلــد ‪ .....‬قائ ـ ً‬\n      ‫األرض رقــم ‪ .....‬مــن الوحــدة الواقعــة بحــي ‪ ...................‬باملخطــط رقــم‬\n      ‫‪ .....‬يف ‪1393/8/21‬ه ـ احملــدودة شــما ًال بالقطعــة رقــم ‪ .....‬وجنوب ـ ًا‬\n      ‫القطعــة رقــم ‪ .....‬وشــرق ًا ممــر مشــاة عرضــة ســتة أمتــار وغرب ـ ًا شــارع‬\n      ‫عرضــه اثنــا عشــر متــر ًا بطــول عشــرين متــر ًا مــن كل جهــة ومســاحتها‬\n\n‫‪231‬‬\n\f‫أربعمائــة متــر مربــع ‪400‬م‪ 2‬واململوكــة مبوجــب الصــك الصــادر مــن‬\n‫كتابــة عــدل األحســاء األولــى برقــم ‪ .....‬يف ‪ ..........‬مببلــغ خمســة وســتني‬\n‫ا وقبــل اإلفــراغ لــي جاءنــي شــقيقي ‪...‬‬      ‫ألــف ريـ‪ 65000‬ــال دفعتــه كامـ ً‬\n‫وطلــب منــي أن أفــرغ لــه األرض املذكــورة صــورة ال حقيقــة لكــي يقــوم‬\n‫بالتقــدم بهــا إلــى صنــدوق التنميــة العقاريــة وليأخــذ قرضـ ًا ســكني ًا ثــم‬\n‫يعيدهــا لــي فقمــت بتكليــف البائــع باإلفــراغ لشــقيقي ‪...‬صــورة ولــم‬\n‫يدفــع ‪ ...‬شــيئ ًا فقــام باإلفــراغ لــه بتاريــخ ‪1425/4/11‬ه ـ ثــم إن شــقيقي‬\n‫‪...‬تــويف بتاريــخ ‪1427/2/23‬ه ـ ولــم يعــد لــي األرض ولــم يســتفيد مــن‬\n‫القــرض وحيــث إن إفراغــي لشــقيقي ‪...‬كان صــورة ال حقيقــة وذلــك‬\n‫بطلــب منــه وحيــث إنــه تــويف ولــم يســتفد مــن القــرض لــذا أطلــب إلــزام‬\n‫ورثتــه باإلفــراغ لــي هــذه دعــواي وبعرض ذلك علــى املدعى عليهما أجاب‬\n‫ال ونحن‬   ‫قائلــن مــا ذكــره املدعــي يف دعــواه صحيــح كله جملــة وتفصي ً‬\n‫ســمعنا مــن ‪...‬ذلــك ونقــر بــه هكــذا ذكــرا وحيــث إن مــن ضمــن ورثــة‬\n‫‪...‬قاصــر وهــو ابنــه ‪...‬فقــد طلبــت مــن املدعــى البينــة علــى طبــق دعــواه‬\n‫فأحضــر للشــهادة وأدائهــا ‪...‬الســعودي بالســجل املدنــي رقــم ‪...‬وبســؤاله‬\n‫ا إنــي مولــود عــام ‪1388‬ه ـ وأســكن‬          ‫عمــا لديــه مــن الشــهادة أجــاب قائـ ً‬\n‫بحــي ‪ .....‬بالهفــوف ومهنتــي موظــف ب ـ ‪ ...............‬وأنــا شــقيق املدعــي ‪...‬‬\n‫وأشــهد بــاهلل بأنــي ســمعت مــرار ًا مــن أخــي ‪...‬أنــه طلــب مــن أخــي ‪...‬أن‬\n‫يفــرغ لــه قطعــة األرض رقــم ‪ 414‬الواقعــة يف منســوبي التعليــم صــورة ال‬\n‫حقيقــة لكــي يتقــدم بهــا ألخــذ القــرض مــن صنــدوق التنميــة العقاريــة‬\n‫وقــد قــام أخــي ‪...‬باإلفــراغ لــه حســب مــا طلــب منــه علــى أن يعيــد األرض‬\n‫بعــد ذلــك ثــم إن شــقيقي ‪...‬تــويف ولــم يخــرج القــرض وأنــا أشــهد بــأن‬\n‫األرض رقــم ‪ .....‬ملــك ألخــي ‪...‬وليســت ألخــي ‪...‬وإمنــا أفرغهــا باســمه‬\n\n\n                                                                                           ‫‪232‬‬\n\f      ‫صــورة ملــا ذكــرت هــذا مالــدي مــن الشــهادة وبعــرض تلــك الشــهادة علــى‬\n      ‫املدعــى عليهمــا أجابــا قائلــن مــا جــاء يف شــهادة الشــاهد صحيــح جملــة‬\n      ‫و تفصيــا ونحــن نقربــه والشــاهد عــدل ثقــة هــذا مــا لدينــا وبســؤال‬\n      ‫ا لــدي شــقيقتي ‪...‬و‪......‬‬          ‫املدعــى هــل لديــك زيــادة بينــه أجــاب قائ ـ ً‬\n      ‫وأطلــب ســماع مــا لديهمــا هكــذا ذكــر وقــد حضــرت ‪ ...‬الســعودية‬\n      ‫بالســجل املدنــي رقــم ‪...‬وبســؤالها عمــا لديهــا مــن الشــهادة أجابــت قائلــة‬\n      ‫إنــي مولــودة عــام ‪1386‬ه ـ وأســكن بحــي البندريــة بالهفــوف وأنــا ربــة‬\n      ‫منــزل وشــقيقة للمدعــي وأشــهد بــاهلل بأنــي ســمعت مــن شــقيقي ‪...‬يف‬\n      ‫حياتــه مــرار ًا أنــه طلــب مــن شــقيقي ‪...‬أن يفــرغ باســمه قطعــة األرض رقم‬\n      ‫‪ .....‬الواقعــة يف ‪ ............‬لكــي يســتفيد منهــا للتقــدمي لصنــدوق التنميــة‬\n      ‫العقاريــة وقــد أفرغهــا ‪ ...‬لــه‪ ...‬ولــم يدفــع ‪...‬شــيئ ًا وإمنــا أفرغهــا لــه صــورة‬\n      ‫ال حقيقــة لكــي يســتفيد مــن القــرض فيمــا بعــد وقــد تــويف شــقيقي‬\n      ‫‪...‬قبــل أن يفرغهــا باســم أخــي ‪...‬وأنــا أشــهد بــأن األرض املذكــورة ملــك‬\n      ‫ألخــي ‪...‬وليســت ألخــي ‪...‬وأن إفراغهــا ‪...‬لــه‪ ...‬كان صوري ـ ًا هــذا مــا‬\n                                                                             ‫لــدي مــن الشــهادة‬\n      ‫وبعــرض تلــك الشــهادة علــى املدعــي عليهمــا أجابــا قائلــن مــا جــاء‬\n      ‫ا ونحــن نقربــه والشــاهدة‬            ‫يف شــهادة الشــاهدة صحيــح جملــة وتفصي ـ ً‬\n      ‫صاحبــة عدالــة وثقــه هكــذا ذكــرا كمــا أحضــر املدعــي للشــهادة‬\n      ‫وأدائهــا ‪...‬الســعودية بالســجل املدنــي رقــم ‪...‬وبســؤالهما عمــا لديهــا‬\n      ‫مــن الشــهادة أجابــت قائلــة إنــي مولــودة عــام ‪1393‬ه ـ وأســكن بحــي‬\n      ‫‪ ..........‬بالهفــوف وأنــا ربــة منــزل وشــقيقة للمدعــي ‪...‬وأشــهد بــاهلل‬\n      ‫بأنــي ســمعت مــن أخــي ‪ ...‬يف حياتــه مــرار ًا أنــه طلــب مــن أخــي ‪...‬أن‬\n      ‫يفــرغ لــه قطعــة األرض رقــم ‪ ......‬الواقعــة يف ‪....................................‬‬\n\n\n‫‪233‬‬\n\f‫صــورة ال حقيقــة لكــي يســتفيد منهــا للتقــدمي لــدى صنــدوق التنميــة‬\n‫العقاريــة فقــام شــقيقي ‪...‬باإلفــراغ لــه علــى أن يعيدهــا لــه فيمــا بعــد إال‬\n‫أن شــقيقي ‪...‬تــويف قبــل أن يعيدهــا علــى أخــي ‪...‬ولــم يظهــر القــرض ل‪...‬‬\n‫وأنــا أشــهد بــاهلل بــأن قطعــة األرض املذكــورة ملــك لشــقيقي ‪...‬وليســت‬\n‫ل‪ ...‬وإمنــا نقلــت باســم ‪ ...‬صــورة ولــم يدفــع شــيئ ًا مــن قيمتهــا هــذا مــا‬\n‫لــدي مــن الشــهادة وبعــرض تلــك الشــهادة علــى املدعــى عليهمــا أجابــا‬\n‫ا ونحــن نقــر‬ ‫قائلــن مــا جــاء يف شــهادة الشــاهدة صحيــح جملــة وتفصيـ ً‬\n‫بــه والشــاهدة ثقــة وذات عدالــة هــذا مــا لدينــا هــذا وقــد جــرى تعديــل‬\n‫الشــهود والتعريــف بجميــع النســاء املذكــورات مــن قبــل كل مــن‬\n‫‪...‬الســعودي بالســجل املدنــي رقــم ‪...‬و‪...‬الســعودي بالســجل املدنــي رقــم‪...‬‬\n‫هــذا وقــد جــرى االطــاع علــى صــك حصــر الورثــة رقــم ‪ ......‬املذكــور‬\n‫ويتضمــن وفــاة ‪...‬وانحصــار ورثتــه يف والــده ‪ ......‬وزوجتــه ‪...‬ويف ابنــه‬\n‫القاصــر ‪...‬املولــود بتاريــخ ‪1427/9/27‬ه ـ كمــا جــرى االطــاع علــى‬\n‫صــك الواليــة رقــم ‪ ......‬املذكــور ويتضمــن إقامــة املــرأة ‪...‬املذكــورة‬\n‫وليــة علــى ابنهــا القاصــر ‪...‬املذكــور كمــا جــرى االطــاع علــى صــك‬\n‫التملــك رقــم ‪ ......‬املذكــور ويتضمــن مــا ذكــره املدعــي وهــو باســم‬\n‫‪...‬وقــد جــرى االستفســار عــن ســريان مفعولــه فوردتنــا إفــادة كتابــة‬\n‫عــدل األحســاء األولــى برقــم ‪ ......‬يف ‪ ............‬ه ـ وتتضمــن أن الصــك‬\n‫مطابــق لســجله وســاري املفعــول هــذا وباالطــاع عليــه تبــن صالحيتــه‬\n‫لإلفــراغ ونقــل امللكيــة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n‫وحيــث أقــر املدعــى عليهمــا مبــا جــاء يف دعــوى املدعــي وحيــث أقــام‬\n‫املدعــى البينــة املعدلــة وهــي رجــل وامرأتــان علــى طبــق دعــواه وحيــث إن‬\n‫بينتــه موصلــة كمــا أنهــا كافيــة يف إثبــات احلــق لقولــه تعالــى (فرجــل‬\n\n\n                                                                                       ‫‪234‬‬\n\f      ‫وامرأتــان ممــن ترضــون مــن الشــهداء ) اآليــة لــذا فقــد ثبــت لــدي متلــك‬\n      ‫املدعــي لقطعــة األرض املدعــى بهــا وقــررت الشــرح علــى صــك التملــك‬\n      ‫املذكــور مبوجبــه علــى أن ال ينفــذ ذلــك إال بعــد تصديقــه مــن محكمــة‬\n      ‫االســتئناف لوجــود قاصــر وبــه حكمــت وبعــرض احلكــم علــى الطرفــن‬\n      ‫قــررا قناعتهمــا بــه وســوف ترفــع املعاملــة إلــى محكمــة االســتئناف إن‬\n      ‫شــاء اهلل لتدقيــق احلكــم حســب املتبــع وللبيــان حــرر يف ‪1434/5/5‬ه ـ‬\n                     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n      ‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/1180012‬ش‪ 2‬وتاريــخ‬\n      ‫‪1434/5/14‬ه ـ والــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة األحســاء برقــم ‪ 34/519564‬وتاريــخ ‪1434/5/8‬ه ـ املرفــق‬\n      ‫بهــا الصــك الصــادر مــن فضيلــة مســاعد رئيســها الشــيخ ‪...‬املســجل برقــم‬\n      ‫‪ 34207046‬وتاريــخ ‪1434/5/6‬ه ـ اخلــاص بدعــوى‪... /‬ضــد‪ /‬ورثــة ‪...‬يف‬\n      ‫قضيــة إفــراغ عقــار وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى حكــم فضيلتــه واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                         ‫محمــد وآلــه وصحبــه وســلم حــرر يف‪1434/6/27‬ه ـ ‪.‬‬\n\n\n\n\n‫‪235‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":230,"source_page_end":235,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8a5debd1cbb064037c4de397c465cc1bc0381b2d5e844ea700074c78a427adc5","normalized_text_hash":"0c0d6945ae896253036b4590920ebe996179eddb530588aa74f751768232331a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p230-34207046"},{"id":"cd10dc2e-6f98-53b5-b792-257cf59650ac","document_type":"judgment","category":"judicial","subcategory":"general","title":"عقد -بيع -محطة محروقات -مطالبة بفرق سعر البيع للضرر بسبب الغش والتدليس -بيع العقار بعد العلم بالعيب يعد رض ا بالعيب -سقوط املطالبة بأرش النقص بالتصرف بعد العلم بالعيب -احلكم برد الدعوى وعدم االستحقاق .","document_number":"34257807","case_number":"34244543","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/3","year":"1434","subject":"عقد -بيع -محطة محروقات -مطالبة بفرق سعر البيع للضرر بسبب الغش والتدليس -بيع العقار بعد العلم بالعيب يعد رض ا بالعيب -سقوط املطالبة بأرش النقص بالتصرف بعد العلم بالعيب -احلكم برد الدعوى وعدم االستحقاق .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/7/3 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34257807 :‬‬\n                   ‫َر ْق ُم الدعوى‪34244543 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34288442‬تاريخه‪1434/8/6 :‬هـ‬\n\n\n‫عقــد ‪ -‬بيــع ‪ -‬محطــة محروقــات ‪ -‬مطالبــة بفــرق ســعر البيــع للضــرر‬\n‫بســبب الغــش والتدليــس ‪ -‬بيــع العقــار بعــد العلــم بالعيــب يعــد رض ـ ًا‬\n‫بالعيــب ‪ -‬ســقوط املطالبــة بــأرش النقــص بالتصــرف بعــد العلــم‬\n                    ‫بالعيــب ‪ -‬احلكــم بــرد الدعــوى وعــدم االســتحقاق ‪.‬‬\n\n\n\n\n‫جــاء يف املغنــي ‪( 243/6‬إذا بــاع املعيــب ثــم أراد أخــذ أرشــه فظاهــر كالم‬\n‫اخلرقــي أنــه ال أرش لــه ســواء باعــه عامل ـ ًا بعيبــه أو غيــر عالــم وهــذا‬\n‫مذهــب أبــي حنيفــة والشــافعي ‪ )..‬ينظــر أيضـ ًا كشــاف القنــاع ‪457/7‬‬\n                                                                                ‫‪.‬‬\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه مبطالبتــه بفــرق ســعر بيــع‬\n‫العقــار بســبب الضــرر احلاصــل بالغــش والتدليــس مــن املدعــى عليــه‬\n‫‪ ،‬حيــث اشــترى موكلــه مــن املدعــى عليــه محطــة محروقــات مببلــغ‬\n‫إجمالــي قــدره أربعــة ماليــن ومائتــا ألــف ريــال ومبــا أن احملطــة تعمــل‬\n‫بــدون رخصــة بلديــة فقــد اشــترط موكلــه علــى البائــع املدعــى عليــه يف‬\n‫عقــد البيــع بــأن احملطــة قــد شــيدت حســب مواصفــات البلديــة والدفــاع‬\n‫املدنــي وعنــد متابعــة موكلــه للمعاملــة لــدى أمانــة مكــة والبلديــة تبــن‬\n\n\n                                                                                    ‫‪236‬‬\n\f      ‫ملوكلــه بأنــه ال ميكــن إصــدار رخصــة مــن البلديــة ممــا يخالــف اإلتفــاق‬\n      ‫ا ســوى بيــع املوقــع مببلــغ ثالثــة ماليــن‬ ‫مــع البائــع ولــم يجــد موكلــه حـ ً‬\n      ‫ريــال بخســارة قدرهــا مليــون ومائتــا ألــف ريــال علم ـ ًا بأنــه لــم يســتطع‬\n      ‫تشــغيل املوقــع بســبب إقفالــه مــن قبــل البلديــة ويطالــب إلــزام املدعــى‬\n      ‫عليــه بدفــع فــرق البيــع بســبب الضــرر الــذي وقــع علــى موكلــه بســبب‬\n      ‫غشــه وتدليســه ‪ ،‬أجــاب املدعــى عليــه بــأن املدعــي يعلــم بــأن احملطــة‬\n      ‫ليــس عليهــا تصريــح مــن البلديــة وقــد قــام بتشــغيلها فتــرة وبقيــت حتــت‬\n      ‫يــده حتــى باعهــا ومبــا أن املدعــي يعلــم بعــدم وجــود تصريــح وتصــرف‬\n      ‫بالعقــار ببيعــه وطلــب صــرف النظــر عــن دعــوى املدعــي ‪ ،‬صــادق املدعي‬\n      ‫وكالــة علــى علــم موكلــه بعــدم وجــود تصريــح للمحطــة قبــل الشــراء‬\n      ‫وتشــغيلها ‪ ،‬ومبــا أن موكلــه كان يعلــم أن احملطــة بــدون تصريــح‬\n      ‫وأنــه تقــدم بعــد الشــراء مباشــرة بطلــب إصــدار تصريــح للبلديــة وأبلغتــه‬\n      ‫بالرفــض يف ‪1431/2/2‬ه ـ ثــم بقــي العقــار بيــده طيلــة هــذه املــدة حتــى‬\n      ‫باعــه منــذ خمســة أشــهر وألن املدعــي أصالــة دخــل علــى بصيــرة يف هــذا‬\n      ‫العقــد ثــم تصــرف بالبيــع بعــد مضــي حوالــي خمــس ســنوات مــن الشــراء‬\n      ‫وبعــد رفــض البلديــة إعطــاءه تصريــح بثــاث ســنوات وألنه لــو كان عيبا‬\n      ‫ثابتــا فإنــه بيعــه للعقــار بعــد علمــه بهــذا العيــب يعــد رضــا منــه بالعيــب‬\n      ‫وال يجــوز لــه املطالبــة بــأرش النقــص وهــذا هــو الراجــح مــن أقــوال أهــل‬\n      ‫العلــم ينظــر املغنــي ‪ 243/6‬وكشــاف القنــاع ‪ ، 457/7‬احلكــم بــرد‬\n      ‫دعــوى املدعــي أصالــة وعــدم اســتحقاقه ملــا يدعيــه وإخــاء ســبيل‬\n      ‫املدعــى عليــه مــن هــذه الدعــوى ‪ ،‬قنــع املدعــى عليــه باحلكــم واعتــرض‬\n      ‫املدعــي وكالــة بالئحــة ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة اخلامســة‬\n                                 ‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n‫‪237‬‬\n\f‫احلمد هلل وحده وبعد فلدي أنا ‪ ......‬القاضي يف احملكمة العامة مبكة‬\n‫املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة مبكــة املكرمــة برقــم ‪ 34244543‬وتاريــخ ‪ 1434/05/27‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341290978‬وتاريــخ ‪ 1434/05/27‬هـ حضر‬\n‫‪ ......‬بالســجل املدني ‪ ......‬بوكالته عن ‪ ......‬مبوجب الوكالة الصادرة‬\n‫مــن كتابــة العــدل الثانية بالريــاض برقم‪34203449‬يف‪1434/2/19‬هـ‬\n‫والتــي تخولــه اقامــة وســماع الدعــاوي واملرافعــة واملدافعــة ‪ ...‬الــخ وادعى‬\n‫علــى احلاضــر معــه ‪ ......‬بالســجل املدنــي رقــم (‪ )......‬وادعــى علــى احلاضــر‬\n‫معــه قائــا يف دعــواه لقــد اشــترى موكلــي من املدعــى عليه هذا احلاضر‬\n‫محطــة محروقــات علــى طريــق ‪ ...‬بالصك الشــرعي رقــم (‪)3/425/155‬‬\n‫وتاريــخ ‪1425/7/8‬ه ـ مصــدره كتابــة العــدل االولــى مبكــة املكرمــة‬\n‫وذلــك مبقابــل مبلــغ وقــدره اربعــة ماليــن ومائتــا الــف ريــال فقــط ال غيــر‬\n‫وحيــث ان احملطــة كانــت تعمــل بــدون رخصــه بلديــة فانــه قــد اشــترط‬\n‫موكلــي علــى البائــع يف عقــد البيــع بــأن االرض املذكــورة أعــاه واملقام‬\n‫عليهــا محطــة محروقــات قــد شــيدت كمــا هــو مذكــور يف الصــك‬\n‫حســب مواصفــات البلديــة والدفــاع املدنــي ‪...‬الــخ مرفــق (صــورة مــن‬\n‫العقــد) وعنــد متابعــة موكلــي للمعاملــة لــدى أمانــة العاصمــة املقدســة‬\n‫وبلديــة الشــرائع الفرعيــة تبــن ملوكلــي بأنــه ال ميكــن اصــدار رخصــة‬\n‫مــن البلديــة للموقــع (مرفــق صــورة مــن خطــاب البلديــة ) ممــا يخالــف‬\n‫ا ســوى بيــع املوقــع مببلــغ ثالثــة‬\n                                     ‫االتفــاق مــع البائــع ولــم يجــد موكلــي حـ ً‬\n‫ماليــن ريــال بخســارة قدرهــا مليــون ومائتــا الــف ريــال علمــا بأنــه لــم‬\n\n                                                                                        ‫‪238‬‬\n\f      ‫يســتطع تشــغيل املوقــع بســبب اقفالــه مــن قبــل البلديــة فأطلــب الــزام‬\n      ‫املدعــى عليــه بدفــع فــرق البيــع بســبب الضــرر الــذي وقــع علــى موكلــي‬\n      ‫بســبب غشــه وتدليســه وقــدر املبلــغ مليــون ومئتــا الــف ريــال فقــط ال غيــر‬\n      ‫علمـ ًا بــأن موكلــي قــد اخطــر البائــع مبــا حصــل لــه وطالبــه بدفــع الفــرق‬\n      ‫ولكنــه جتاهــل الطلــب هــذه دعــوى موكلــي وبســؤال املدعــى عليــه عــن‬\n      ‫دعــوى املدعــي قــال اطلــب امهالــي إلحضــار إجابتــي أجــاب قائــا إننــي‬\n      ‫بعــت هــذا العقــار املنشــأ عليــه محطــة وقــود بتاريــخ ‪1429/4/9‬ه ـ ومت‬\n      ‫إفــراغ الصــك للمدعــي أصالــة واملدعــي أصالــة يعلــم أن احملطــة بــدون‬\n      ‫تصريــح مــن قبــل البيــع وقــد طلــب منــي وكالــة الســتخراج تصريــح‬\n      ‫للمحطــة وأعطيتــه وكالــة بذلــك وملــا أفرغــت العقــار لــه قــام بتشــغيل‬\n      ‫احملطــة مــدة معينــه وراجــع البلديــة الســتخراج تصريــح واســتمر العقــار‬\n      ‫بيــده حتــى بدايــة هــذه الســنة ثــم باعــه وأفرغــه للمشــتري ولــذا والن‬\n      ‫املدعــي أصالــة يعلــم أن احملطــة بــا تصريــح وتصــرف يف العقــار ببيعــه‬\n      ‫فــا حــق لــه يف هــذه الدعــوى وأنــا لــن أدفــع لــه أي مبلــغ وأطلــب صــرف‬\n      ‫النظــر عــن دعــواه هــذه إجابتــي وبعــرض ذلــك علــى املدعــي وكالــة قــال‬\n      ‫صحيــح أن موكلــي يعلــم أن احملطــة بــا تصريــح قبــل شــرائه لهــا وانــه‬\n      ‫قــام بتشــغيل احملطــة ولكــن كانــت مــدة تشــغيله لهــا هــي شــهران فقــط‬\n      ‫هكــذا قــرر فطلبــت مــن املدعــي وكالــه صــك العقار فقــال إن موكلي‬\n      ‫قــد أفرغــه للمشــتري قبــل خمســة أشــهر ولكنــي أحضــرت صــورة مــن‬\n      ‫هــذا الصــك قبــل اإلفــراغ وأبــرز صــورة الصــك الصــادرة مــن كتابــة‬\n      ‫العــدل األولــى مبكــة برقــم ‪ 3/425/155‬يف ‪1425/7/8‬ه ـ وباالطــاع‬\n      ‫عليهــا وجدتــه يتضمــن شــراء ‪ ......‬لكامــل العقــار احملــدودة واملذروعــه‬\n      ‫باطنــه املنشــأ عليــه محطــة بنزيــن مشــتملة علــى مظلــة كبيــرة حتتهــا‬\n\n\n‫‪239‬‬\n\f‫ثمانيــة عشــر مضخــة بنزيــن وســت مضخــات ديــزل وحتتهــا ســتة خزانات‬\n‫للبنزيــن والديــزل واســتراحة مكونــه مــن أربــع غــرف بحماماتهــا وفنــدق‬\n‫عبــارة عــن مطعــم مبنافعــه الشــرعية وبوايــك عبــارة عــن قهــوة مبنافعهــا‬\n‫ودكانــن أحداهمــا كهربائــي ســيارات واألخــرى محــل إلصــاح‬\n‫البنشــر مجهزيــن بــكل مــا يلزمهمــا وغرفــه بهــا مواطيــر الكهربــاء‬\n‫ومســجد كبيــر منافعــه الشــرعية إلقامــة الصــاة فيــه مبوجــب صــك‬\n‫اإلنشــاء الصــادر مــن احملكمــة الكبــرى مبكــة برقــم ‪12/27‬‬\n‫يف‪1433/5/10‬ه ـ إ‪.‬ه ـ ثــم أحلــق بــه بتاريخ ‪1429/4/9‬ه ـ انتقال ملكية‬\n‫العقــار الــى ‪ ......‬مببلــغ أربعــة ماليــن ومائتــي ريــال إ‪.‬ه ـ وبســؤال املدعــي‬\n‫وكالــه هــل اســتلم موكلــه كامــل اإلنشــاءات واحملتويــات املذكــورة‬\n‫يف صــك اإلفــراغ فقــال نعــم لقــد اســتلمها موكلــي هكــذا قــرر كمــا‬\n‫ســألت املدعــي وكالــه هــل تقــدم موكلــه بطلــب تصريــح البلديــة‬\n‫فقــال نعــم لقــد تقــدم موكلــي الــى البلديــة إلصــدار تصريــح للمحطــة‬\n‫بعــد الشــراء مباشــرة ولكنهــا رفضــت طلــب موكلــي وذلــك يف عــام‬\n‫‪1431/2/22‬ه ـ هكــذا قــرر فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابة‬\n‫وبعــد االطــاع علــى نســخة مــن صــك اإلفــراغ والن املدعــي وكالــه أقــر‬\n‫أن موكلــه اســتلم العقــار بجميــع احملتويــات واإلنشــاءات املدونــة يف‬\n‫صــك اإلفــراغ وأن موكلــه كان يعلــم ان احملطــة بــدون تصريــح وانــه‬\n‫تقــدم بعــد الشــراء مباشــرة بطلــب إصــدار تصريــح للبلديــة وأنهــا أبلغتــه‬\n‫بالرفــض يف ‪1431/2/2‬ه ـ ثــم بقــي العقــار بيــده طيلــة هــذه املــدة حتــى‬\n‫باعــه منــذ خمســة أشــهر والن املدعــي أصالــة دخــل علــى بصيــرة يف هــذا‬\n‫العقــد ثــم تصــرف بالبيــع بعــد مضــي حوالــي خمــس ســنوات مــن الشــراء‬\n‫وبعــد رفــض البلديــة إعطــاءه تصريــح بثــاث ســنوات وألنه لــو كان عيبا‬\n\n\n                                                                                        ‫‪240‬‬\n\f      ‫ثابتــا فإنــه بيعــه للعقــار بعــد علمــه بهــذا العيــب يعــد رضــا منــه بالعيــب وال‬\n      ‫يجــوز لــه املطالبــة بــارش النقــص وهــذا هــو الراجــح مــن أقــوال أهــل العلم‬\n      ‫ينظــر املغنــي ‪ 246/6‬وكشــاف القنــاع ‪ 457/7‬قــال املوفــق يف املغنــي‬\n      ‫‪ 243/6‬اذا بــاع املعيــب ثــم أراد اخــذ ارشــه فظاهــر كالم اخلرقــي أنــه ال‬\n      ‫أرش لــه ســواء باعــه عاملــا بعيبــه او غيــر عالــم وهــذا مذهــب ابــي حنيفــه‬\n      ‫والشــافعي ألن امتنــاع الــرد كان بفعلــه فاشــبه مــا لــو أتلــف املبيــع وألنــه‬\n      ‫قــد اســتدرك ظالمتــه ببيعــه فلــم يكــن لــه أرش كمــا لــو زال العيــب‬\n      ‫وقــال القاضــي ان باعــه بعــد علمــه بالعيــب فــا أرش لــه لرضــاه بــه معيبــا‬\n      ‫وإن باعــه غيــر عالــم بالعيــب فلــه األرش نــص عليــه احمــد إ‪.‬ه ـ لذلــك‬\n      ‫كلــه فقــد حكمــت بــرد دعــوى املدعــي أصالــة وعــدم اســتحقاقه ملــا‬\n      ‫يدعيــه وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى وبعــرض احلكــم‬\n      ‫علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر املدعــي وكالــة عــدم‬\n      ‫القناعــة وطلــب رفعــه حملكمــة االســتئناف بعــد تقــدمي الئحــة اعتراضيــة‬\n      ‫عليــه فأفهمتــه مبراجعــة احملكمــة خــال عشــرة أيــام الســتالم صــورة‬\n      ‫الصــك وتقــدمي الالئحــة االعتراضيــة خــال ثالثــن يومــا مــدة االعتــراض‬\n      ‫فــإذا تأخــر ســقط حقــه يف طلب االســتئناف واكتســب احلكــم القطعية‬\n      ‫‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                         ‫وســلم ‪ .‬حــرر يف ‪ 1434/7/1‬ه ـ‬\n      ‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬نحــن‬\n      ‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪ ......‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‬\n      ‫املســجل بعــدد ‪ 34257807‬وتاريــخ ‪1434/7/3‬ه ـ املتضمــن دعــوى ‪......‬‬\n\n\n‫‪241‬‬\n\f‫ضــد ‪ ......‬احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم‬\n‫وص ــورة ضبط ــه والئحتــه االعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‪.‬‬\n‫وباهلل التوفيق وصل ــى اهلل عل ــى نبينا محمد وعل ــى آل ــه وصحب ــه وسلم ‪.‬‬\n\n\n\n\n                                                                               ‫‪242‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":236,"source_page_end":242,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"fdc5b083e48b3744f740ab64527e2ae833080b9216aa68b34b34e1080a50990e","normalized_text_hash":"a295e50ee5184c4b3386fe3910b752a31816485238de26d92ddb058a42ebce9f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p236-34257807"},{"id":"3e3881b1-fea5-58c3-8508-fa8d84f4ffdd","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقد -أرض بيضاء -املطالبة برد ثمن املبيع لعدم التملك- اإلقرار بقبض الثمن واحليازة دون صك شرعي -العقد من مالك للمعقود عليه أو من يقوم مقامه -احلكم برد الثمن وعدم صحة","document_number":"34273692","case_number":"34268669","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/19","year":"1434","subject":"بيع -عقد -أرض بيضاء -املطالبة برد ثمن املبيع لعدم التملك- اإلقرار بقبض الثمن واحليازة دون صك شرعي -العقد من مالك للمعقود عليه أو من يقوم مقامه -احلكم برد الثمن وعدم صحة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/19 :‬هـ‬\n                      ‫ُ‬                  ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34273692 :‬‬\n                          ‫َر ْق ُم الدعوى‪34268669 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34307016‬تاريخه‪1434/8/28 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــد ‪ -‬أرض بيضــاء ‪ -‬املطالبــة بــرد ثمــن املبيــع لعــدم التملــك‪-‬‬\n      ‫اإلقــرار بقبــض الثمــن واحليــازة دون صــك شــرعي ‪ -‬العقــد مــن مالك‬\n      ‫للمعقــود عليــه أو مــن يقــوم مقامــه ‪ -‬احلكــم بــرد الثمــن وعــدم صحــة‬\n                                                                            ‫البيــع ‪.‬‬\n\n\n\n      ‫‪ -1‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬وال تبــع مــا ليــس عنــدك)‪ .‬رواه‬\n                                                                        ‫ابــن ماجــه‪.‬‬\n      ‫‪ -2‬قــال يف الــروض املربــع (ص‪ )247‬الشــرط الرابــع‪« :‬أن يكــون العقــد‬\n                            ‫مــن مالــك للمعقــود عليــه أو مــن يقــوم مقامــه»‪.‬‬\n\n\n\n      ‫ادعــى وكيــل املدعــي بــأن موكلــه اشــترى مــن املدعــى عليــه أرض ـ ًا‬\n      ‫بيضــاء وســلمه ثمنهــا بعــد أن ذكــر ملوكلــه عنــد البيــع أن األرض‬\n      ‫مملوكــة لــه مــن ضمــن أرض قبيلتــه وأن القبيلــة متلكهــا بصــك عــام‬\n      ‫ثــم اتضــح أن األرض ال ميلكهــا املدعــى عليــه وال قبيلتــه ‪ ،‬ولــذا فقــد‬\n      ‫طلــب احلكــم عليــه بــأن يعيــد لــه املبلــغ الــذي دفعــه لــه ‪ ،‬أقــر املدعــى‬\n      ‫عليــه مبــا جــاء يف الدعــوى ودفــع بأنــه اتفــق مــع املدعــي عنــد البيــع علــى‬\n      ‫حمايتــه مــن أي شــخص يطمــع يف األرض ‪ ،‬املدعــى عليــه أقــر بأنــه بــاع‬\n      ‫أرضـ ًا بيضــاء ليــس عليهــا إثبــات متلــك ومــن شــروط صحــة البيــع امللــك‪،‬‬\n‫‪243‬‬\n\f‫قضــت احملكمــة بعــدم صحــة البيــع وحكمــت بإعــادة املبلــغ املدعــى بــه‬\n‫إلــى املدعــي ‪ ،‬عــارض املدعــى عليــه علــى احلكــم ‪ ،‬قــررت محكمــة‬\n                                        ‫االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باملدينــة املنورة‪/‬املســاعد برقــم ‪ 34268669‬وتاريــخ‬\n‫‪1434/06/12‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341412790‬وتاريــخ‬\n‫‪ 1434/06/12‬ه ـ ففــي يــوم األربعــاء املوافــق ‪1434/07/19‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 : 01‬وفيهــا حضــر (‪ )........‬ســعودي بالســجل‬\n‫املدنــي رقــم (‪ )........‬بالوكالــة عــن مبوجــب الوكالــة رقــم ‪ 39‬وتاريــخ‬\n‫‪1434/05/22‬ه ـ الصــادرة مــن كتابــة عــدل خيبــر والتــي تتضمــن أن له‬\n‫حــق مطالبــة املدعــى عليــه مببالــغ ماليــة وحضــور اجللســات وأدعــى علــى‬\n‫احلاضــر معــه (‪ )........‬ســعودي بالســجل املدنــي رقــم (‪ )........‬قائــا يف‬\n‫دعــواه إن موكلــي اشــترى مــن هــذا احلاضــر معــي أرضـ ًا بيضــاء (‪)........‬‬\n‫طريــق (‪ )........‬بتاريــخ ‪1434/02/15‬ه ـ مببلــغ وقــدره ثالثــون ألــف ريــال‬\n‫وقــد ذكــر ملوكلــي عنــد البيــع أن األرض مملوكــة لــه مــن ضمــن أرض‬\n‫قبيلــة (‪ )........‬وأن القبيلــة متلكهــا بصــك عــام ثــم اتضــح لــي أن األرض ال‬\n‫ميلكهــا وال متلكهــا القبيلــة وحيــث إنــه باعنــي مــا ال ميلــك أطلــب احلكــم‬\n‫عليــه بــأن يعيــد لــي املبلــغ الــذي دفعتــه لــه وقــدره ثالثــون ألــف ريــال‬\n‫وأســأله اجلــواب وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n‫مــن شــراء األرض املذكــورة باملبلــغ املذكــور فصحيــح وأنــا اتفقــت معــه‬\n‫عنــد البيــع أن أحميــه مــن أي شــخص يطمــع يف هــذه األرض ولــم أتفــق‬\n                                                                                      ‫‪244‬‬\n\f      ‫معــه علــى حمايتــه مــن الدولــة واألرض ليــس لــي عليهــا صــك شــرعي‬\n      ‫وإمنــا أنــا متلكتهــا بيــدي وجماعتــي يعرفــون أنهــا لــي وهــي أرض بيضــاء‬\n      ‫ليــس عليهــا أي إحيــاء هكــذا أجــاب فبنــاء علــى مــا تقــدم وملــا ســبق مــن‬\n      ‫الدعــوى واالجابــة وإلقــرار الطرفــن بأنهــا أرض بيضــاء ال إثبــات متلــك‬\n      ‫فيهــا ولقــول النبــي صلــى اهلل عليــه وســلم «وال بيــع مــا ليــس عنــدك»رواه‬\n      ‫ابــن ماجــه وألن مــن شــروط صحــة البيــع امللــك قــال يف الــروض املربــع‬\n      ‫ص‪247‬الشــرط الرابــع «أن يكــون العقــد مــن مالــك للمعقــود عليــه أو‬\n      ‫مــن يقــوم مقامــه» لــذا فقــد ثبــت لــدي عــدم صحــة البيــع وحكمــت‬\n      ‫بإعــادة املبلــغ املدعــى بــه وقــدره ثالثــون ألــف ريــال الــى املدعــي وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه لــم يقنــع باحلكــم وأفهمتــه بــأن عليــه مراجعــة‬\n      ‫احملكمــة خــال عشــرة أيــام الســتالم صــورة مــن صــك احلكــم لتقــدمي‬\n      ‫اعتراضــه عليهــا خــال ثالثــن يومـ ًا مــن تاريــخ اســتالمه واال فــإن حقــه‬\n      ‫مــن االســتئناف يســقط ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/19‬ه ـ‬\n      ‫ويف يــوم الثالثــاء املوافق‪1434/10/27‬ه ـ عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف برقــم ‪ 341412790‬وتاريــخ ‪1434/09/03‬ه ـ واملقيــدة‬\n      ‫يف احملكمــة برقــم ‪ 341412790‬يف ‪1434/09/15‬ه ـ وقــد صــدر‬\n      ‫بشــأنها القــرار رقــم ‪ 34307016‬وتاريــخ ‪1434/08/28‬ه ـ الصــادر مــن‬\n      ‫دائــرة حقوقيــة أولــى مبحكمــة االســتئناف مبكــة املكرمــة واملــدون‬\n      ‫نصــه علــى ظهــر الصــك باملوافقــة علــى احلكــم باألكثريــة ‪ .‬قاضــي‬\n      ‫اســتئناف ختمــه وتوقيعــه‪ ،‬قاضــي اســتئناف (‪ )........‬ختمــه وتوقيعــه‪،‬‬\n      ‫رئيــس الدائــرة لــه وجهــة نظــر (‪ )........‬ختمــه وتوقيعــه‪ ،‬وبــاهلل التوفيــق‬\n      ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪1434/10/27‬ه ـ ‪.‬‬\n‫‪245‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":243,"source_page_end":245,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"10742fd99d0395590117d4ee22f930b33e1a4b75ae869607935d9d9c0fadb77d","normalized_text_hash":"efb154d1c03096a21becea632f8042ccd2f4601efddbc68155bdd1d0bb3e85b3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p243-34273692"},{"id":"ab72896e-851e-54f0-b4c0-99a3d8677c20","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -شراء فله -طلب إعادة العقار وإفراغه باسم املدعى- دفع املدعى عليه بأن العقار ليس حتت يده -دعوى استرداد احليازة يف العقار تقام على من بيده العن -احلكم بصرف النظر عن الدعوى وأن الدعوى تتوجه على من بيده العقار .","document_number":"34270928","case_number":"47158","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/17","year":"1434","subject":"بيع -عقار -شراء فله -طلب إعادة العقار وإفراغه باسم املدعى- دفع املدعى عليه بأن العقار ليس حتت يده -دعوى استرداد احليازة يف العقار تقام على من بيده العن -احلكم بصرف النظر عن الدعوى وأن الدعوى تتوجه على من بيده العقار .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/17 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34270928 :‬‬\n                      ‫َر ْق ُم الدعوى‪47158 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34324633‬تاريخه‪1434/9/23 :‬هـ‬\n\n\n‫بيــع ‪ -‬عقــار‪ -‬شــراء فلــه ‪ -‬طلــب إعــادة العقــار وإفراغــه باســم املدعــى‪-‬‬\n‫دفــع املدعــى عليــه بــأن العقــار ليــس حتــت يــده ‪ -‬دعــوى اســترداد‬\n‫احليــازة يف العقــار تقــام علــى مــن بيــده العــن ‪ -‬احلكــم بصــرف النظــر‬\n            ‫عــن الدعــوى وأن الدعــوى تتوجــه علــى مــن بيــده العقــار ‪.‬‬\n\n\n\n\n                                    ‫قاعدة‪ :‬الدعوى تقام على من بيده العني ‪.‬‬\n\n\n\n\n‫ادعى املدعي أنه اشــترى عقار ًا وقام بتحويل ثمنه حلســاب أخيه املدعى‬\n‫عليــه ‪ ،‬وأن أخــاه املدعــى عليــه حــرر شــيك ًا لبائــع العقــار وقــام بإفــراغ‬\n‫العقــار باســمه ‪ ،‬طلــب املدعــي إلــزام املدعــى عليــه بإعــادة العقــار لــه ‪،‬‬\n‫أقــر املدعــي عليــه بشــراء العقــار موضــع الدعــوى وأنكــر أن يكــون‬\n‫املدعــى هــو الــذي دفــع ثمنــه ‪ ،‬ذكــر املدعــى عليــه بأنــه قــام ببيــع العقــار‬\n‫لشــخص آخــر ‪ ،‬حيــث إن مــن املقــرر أن دعــوى طلــب اســترداد العقــار‬\n‫تقــام علــى مــن بيــده العــن لــذا صــدر احلكــم بصــرف النظــر عــن دعــوى‬\n‫املدعــي وجــرى إفهامــه بــأن دعــواه تقــام علــى مــن بيــده العــن ‪ ،‬اعتــرض‬\n      ‫املدعــي علــى احلكــم ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n                                                                                         ‫‪246‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬املــازم القضائــي لــدى فضيلــة‬\n      ‫الشــيخ ‪...‬القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم‬\n      ‫‪ 47158‬وتاريــخ ‪1430/11/01‬ه ـ املقيــدة باحملكمــة برقــم ‪30148074‬‬\n      ‫وتاريــخ ‪1430/10/29‬ه ـ ففــي يــوم اإلثنــن املوافــق ‪1434/07/17‬ه ـ‬\n      ‫حضــر ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬وادعــى علــى‬\n      ‫احلاضــر معــه ‪...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬بصفتــه‬\n      ‫ا عــن ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬      ‫وكي ـ ً‬\n      ‫بشــرق الريــاض برقــم ‪ 34739814‬يف ‪1434/6/11‬ه ـ املخــول لــه فيهــا‬\n      ‫باملطالبــة واملرافعــة واملدافعــة وســماع الدعــاوى والــرد عليهــا واإلقــرار‬\n      ‫واإلنــكار والصلــح والتنــازل وقبــول األحــكام ونفيهــا واالعتــراض علــى‬\n      ‫ا يف‬ ‫األحــكام وطلــب االســتئناف واالســتالم والتســليم والتوقيــع قائ ـ ً‬\n      ‫دعــواه لقــد اشــتريت مــن فلــة بالريــاض تقــع يف الروضــة بحــي القــدس‬\n      ‫مبنيــة علــى القطعــة رقــم ‪ 67‬والواقعــة يف املخطــط رقــم ‪ 2685‬مبســاحة‬\n      ‫إجامليــة قدرهــا ألــف وأربعمائــة وأربعــة عشــر متــرا مربعــا واململوكــة‬\n      ‫مبوجــب الصــك الشــرعي الصــادر مــن كتابــة عــدل الريــاض رقــم‬\n      ‫‪ 5340‬يف ‪1408/5/17‬ه ـ وذلــك مببلــغ وقــدره مليونــان وخمســمائة‬\n      ‫ألــف ريــال وقــد دفعــت أنــا كامــل املبلــغ وذلــك بتحويلــه إلــى حســاب‬\n      ‫أخــي ‪...‬وبعدهــا قــام ‪...‬بتحريــر شــيك للبائــع ومت إفــراغ الفلــة باســم أخــي‬\n      ‫‪...‬وبعــد فتــرة بــاع ‪ ...‬البيــت لشــخص ال أعــرف اســمه اطلــب إعــادة بيتــي‬\n      ‫لــي هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه مــا‬\n\n‫‪247‬‬\n\f‫ذكــره املدعــي يف دعــواه غيــر صحيــح والصحيــح أن موكلــي اشــترى‬\n‫البيــت مــن مالــه اخلــاص وكتــب باســم موكلــي وقــد باعــه موكلــي‬\n‫قبــل فتــرة وهــو ليــس بيــده اآلن اطلــب رد دعــواه هكــذا أجــاب فبنــاء‬\n‫علــى مــا ســبق مــن الدعــوى واإلجابــة ومبــا أن الطرفــن تصادقــا علــى‬\n‫العقــار ليــس بيــد املدعــى عليــه والدعــوى تقــام علــى مــن بيــده العــن فقــد‬\n‫أفهمــت املدعــي بــأن دعــواه تقــام علــى مــن بيــده العــن وصرفــت النظــر‬\n‫عــن دعــوى املدعــي وبــه حكمــت وبعــرض احلكــم علــى املدعــي قــرر‬\n‫عــدم قناعتــه بــه وأفهمتــه بــأن يتقــدم بالئحتــه االعتراضيــة عليــه خــال‬\n‫ثالثــن يوم ـ ًا فــإن انتهــت املــدة ولــم يتقــدم خاللهــا بالئحتــه اكتســب‬\n‫احلكــم القطعيــة وســقط حقــه يف االســتئناف وبــاهلل التوفيــق وصلــى‬\n‫اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/17‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪1434/11/19‬ه ـ‬\n‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن فضيلــة رئيــس محكمــة‬\n‫االســتئناف بالريــاض برقــم ‪ 34557013‬يف ‪1434/10/8‬ه ـ وبرفقــه‬\n‫قــرار الدائــرة احلقوقيــة اخلامســة رقــم ‪ 34324633‬يف ‪1434/09/23‬ه ـ‬\n‫املتضمــن (وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي اخللــف‬\n‫الشــيخ‪ ... /‬وأحلقــه بذيــل الصــك وصــورة ضبطــه بنــاء علــى قرارنــا رقــم‬\n‫‪ 33474135‬وتاريــخ ‪1433/12/20‬ه ـ لــم يظهــر مــا يوجــب االعتــراض‬\n‫علــى احلكــم بعــد اإلجــراء األخيــر ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n‫محمــد وآلــه وصحبــه وســلم ) انتهــى‪ .‬وحتــى ال يخفــى جــرى إثباتــه وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                              ‫‪1434/11/18‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اخلامســة‬\n\n\n                                                                                       ‫‪248‬‬\n\f      ‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض برقــم‬\n      ‫‪ 33945742‬وتاريــخ ‪1434/7/22‬ه ـ املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة املــازم القضائــي باحملكمــة الشيخ‪.../‬واملســجل برقــم‬\n      ‫‪ 34270928‬وتاريــخ ‪1434/7/17‬ه ـ اخلــاص بدعوى‪.../‬ضد‪.../‬وكالــة‬\n      ‫بشــأن ملكيــة عقــار علــى الصفــة املوضحــة بالصــك واملتضمــن حكــم‬\n      ‫فضيلتــه كمــا هــو موضــح يف الصــك وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض‬\n      ‫علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                           ‫وســلم ‪.‬‬\n\n\n\n\n‫‪249‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":246,"source_page_end":249,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"74e31156fc956bdc725185eb928526eb6a46a872636e1bc44880e9d7aa689371","normalized_text_hash":"38ca60849957e68de98a79ad1c4f68412d47db5d967f163f48308e0aff05aa69","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p246-34270928"},{"id":"e41b8741-3d3e-5c4f-9bb2-47107a356506","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -كفالة غرم وأداء -بيع سيارة على أقساط -سداد جزء من الثمن والعجر عن سداد الباقي -مطالبة الكفيل بتسليم باقي ثمن سيارة اشتراها مكفوله -مصادقة املدعى عليه على الدعوى - إلزام الكفيل بتسليم ما حل من الثمن وسداد املؤجل وقت حلوله -إفهام الكفيل بالرجوع على مكفوله مبا يدفعه عنه إن رغب .","document_number":"34279834","case_number":"34133081","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة عيون اجلواء املنتدب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434 /7 /25","year":"1434","subject":"بيع -كفالة غرم وأداء -بيع سيارة على أقساط -سداد جزء من الثمن والعجر عن سداد الباقي -مطالبة الكفيل بتسليم باقي ثمن سيارة اشتراها مكفوله -مصادقة املدعى عليه على الدعوى - إلزام الكفيل بتسليم ما حل من الثمن وسداد املؤجل وقت حلوله -إفهام الكفيل بالرجوع على مكفوله مبا يدفعه عنه إن رغب .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434 /7 /25 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪34279834:‬‬\n                   ‫َر ْق ُم الدعوى‪34133081 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34234688‬تاريخه‪1434/9/23 :‬هـ‬\n\n\n‫بيــع ‪ -‬كفالــة غــرم وأداء ‪ -‬بيــع ســيارة علــى أقســاط ‪ -‬ســداد جــزء مــن‬\n‫الثمــن والعجــر عــن ســداد الباقــي ‪ -‬مطالبــة الكفيــل بتســليم باقــي‬\n‫ثمــن ســيارة اشــتراها مكفولــه ‪ -‬مصادقــة املدعــى عليــه علــى الدعــوى ‪-‬‬\n‫إلــزام الكفيــل بتســليم مــا حــل مــن الثمــن وســداد املؤجــل وقــت حلولــه‬\n    ‫‪ -‬إفهــام الكفيــل بالرجــوع علــى مكفولــه مبــا يدفعــه عنــه إن رغــب ‪.‬‬\n\n\n\n\n‫املــواد (‪ )2/166‬و(‪ )3/147‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n                                                       ‫التنفيذيــة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بأنــه بــاع علــى طــرف ثالــث (ذكــر اســمه) ســيارة بثمــن‬\n‫مجـ َّـزأ علــى أقســاط شــهرية فكفلــه املدعــى عليــه لديــه كفالــة غــرم‬\n‫وأداء يف ثمــن تلــك الســيارة‪ ،‬وقــد ســدد لــه ذلــك املشــتري جــزء من الثمن‬\n‫ثــم انقطــع عــن الســداد ‪ ،‬لــذا فقــد طلــب إلــزام املدعــى عليــه بســداد مــا‬\n‫بذمــة مكفولــه مــن احلــال واإللتــزام بدفــع الباقي يف أوقــات حلوله ‪ ،‬أقر‬\n‫املدعــى عليــه مبــا جــاء يف الدعــوى ودفــع بأنــه ســلم جــزء مــن املبلــغ احلــال‬\n‫عــن طريــق حوالــة مصرفيــة فصــادق املدعــي علــى ذلــك وعــدل عــن طلبــه‬\n‫بتســليم هــذا القــدر مــن املبلــغ ‪ ،‬املدعــى عليــه أقــر مبــا جــاء يف الدعــوى‬\n\n                                                                                          ‫‪250‬‬\n\f      ‫فللمدعــي احلــق يف مطالبتــه بتســليم املبلــغ احلــال وااللتــزام بدفــع املؤجــل‬\n      ‫يف حينــه لثبوتــه يف الذمــة بالعقــد‪ ،‬قضــت احملكمــة بإلــزام املدعــى‬\n      ‫عليــه بــأن يدفــع للمدعــي املبلــغ احلــال مــن قيمــة الســيارة املوصوفــة يف‬\n      ‫الدعــوى وألزمتــه بدفــع الباقــي أوقــات حلولــه وأفهمتــه بــأن لــه الرجــوع‬\n      ‫علــى مكفولــه مبــا يدفعــه عنــه متــى رغــب ذلــك‪ ،‬قنــع املدعــي باحلكــم‬\n      ‫وعــارض عليــه املدعــى عليــه ‪ ،‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                         ‫علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة عيــون اجلــواء املنتــدب وبنــاء علــى املعاملــة املقيــدة لدينــا‬\n      ‫برقــم ‪34704621‬وتاريــخ ‪ 1434/03/21‬ه ـ ففــي يــوم الســبت‬\n      ‫املوافــق‪ 1434/04/06‬ه ـ افتتحــت اجللســة الســاعة ‪ 11:00‬وفيهــا حضــر‬\n      ‫(‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬أمــا املدعــى‬\n      ‫عليــه (‪ )....‬فلــم يحضــر وقــد انتهــى وقــت اجللســة وزيــادة دون حضــوره وال‬\n      ‫مــن ميثلــه بوكالــة شــرعية ولــم يقــدم عــذر ًا مقبــو ًال أو غيــر مقبــول لــذا‬\n      ‫فقــد قــررت رفــع اجللســة إلحضــاره مــر ًة أخــرى ويف يــوم األحــد املوافــق‬\n      ‫‪ 1434/05/26‬ه ـ افتتحــت اجللســة الثانيــة الســاعة التاســعة والنصــف‬\n      ‫وفيهــا حضــر (‪ )....‬يحمــل الســجل املدنــي رقــم (‪ )....‬امــا املدعــى عليــه‬\n      ‫(‪ )....‬فلــم يحضــر وقــد انتهــى وقــت اجللســة وزيــادة دون حضــوره وال‬\n      ‫مــن ميثلــه بوكالــة شــرعية ولــم يقــدم عــذر ًا مقبــو ًال أو غيــر مقبــول لــذا‬\n      ‫واحلــال مــا ذكــر فقــد قــررت رفــع اجللســة ثــم لــدي أنــا رئيــس احملكمــة‬\n      ‫العامــة يف عيــون اجلــواء وبنــاء علــى قــرار معالــي وزيــر العــدل رقــم ‪10641‬‬\n\n‫‪251‬‬\n\f‫وتاريــخ ‪1434/4/21‬ه ـ املبنــي علــى قــرار املجلــس األعلــى للقضــاء رقــم‬\n‫‪ 34 / 1 / 91‬وتاريــخ ‪1434/4/17‬ه ـ املتضمــن نقلــي لقضــاء احملكمــة‬\n‫العامــة يف عيــون اجلــواء ويف يــوم األربع ـاًء املوافــق ‪1434/7/12‬ه ـ‬\n‫افتتحــت اجللســة الثالثــة الســاعة التاســعة صباحـ ًا وفيهــا حضــر املدعــي‬\n‫واملدعــى عليــه ســعودي بالســجل املدنــي رقــم ثــم جــرى تطبيــق املــادة‬\n‫‪ 2 / 166‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة بتــاوة مــا‬\n‫ســبق ضبطــه علــى املترافعــن فلمــا ســمعاه قــررا بقولهمــا نصــادق علــى‬\n‫مــا ضبــط يف اجللســة الســابقة ثــم ســألت املدعــي عــن دعــواه فادعــى‬\n‫قائ ـاً‪ :‬إنــه بتاريــخ ‪1432/12/28‬ه ـ بعــت علــى املشــتري ‪ .........‬ســيارة‬\n‫داتســون نيســان غمــارة صنــع ســنة ‪ 2007‬م مببلــغ إجمالــي قــدره ســتة‬\n‫وخمســون ألف ـ ًا وخمســمائة ريــال تدفــع علــى أقســاط شــهرية بواقــع‬\n‫ألــف وخمســمائة ريــال وتبــدأ هــذه األقســاط بتاريــخ ‪1433/1/25‬ه وقــد‬\n‫ســدد لــي املشــتري مــن هــذا املبلــغ تســعة عشــر ألف ـ ًا وخمســمائة ريــال‬\n‫ثــم انقطــع عــن الســداد وبقــي بذمتــه مــن إجمالــي املبلــغ ســبعة وثالثــون‬\n‫ألــف ريــال احلــال منهــا حتــى هــذا التاريــخ ســبعة آالف وخمســمائة ريــال‬\n‫والباقــي وقــدره تســعة وعشــرون ألفـ ًا وخمســمائة ريــال حتــل يف أوقاتهــا‬\n‫بواقــع ألــف وخمســمائة ريــال يف اخلامــس والعشــرين مــن كل شــهر تبــدأ‬\n‫مــن ‪1434/7/25‬ه ـ وقــد كفلــه هــذا املدعــى عليــه كفالــة غــرم وأداء‬\n‫وذلــك مبوجــب ورقــة اإلقــرار املؤرخــة يف ‪1432/12/28‬ه ـ أطلــب إلزامه‬\n‫بســداد مــا بذمــة مكفولــه مــن احلــال وقــدره ســبعة آالف وخمســمائة‬\n‫ريــال وااللتــزام بدفــع الباقــي وقــدره تســعة وعشــرون ألف ـ ًا وخمســمائة‬\n‫ريــال يف أوقــات حلولهــا بواقــع ألــف وخمســمائة ريــال يف تاريــخ اخلامــس‬\n‫والعشــرين مــن كل شــهر هــذه دعــواي ‪ ،‬وبعــرض الدعــوى ومــا جــاء‬\n\n\n                                                                                    ‫‪252‬‬\n\f      ‫فيهــا علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي يف دعــواه مــن‬\n      ‫ا للمشــتري علــى صفــة مــا‬    ‫البيــع والثمــن وصفــة املبيــع وكونــي كفي ـ ً‬\n      ‫جــاء يف الدعــوى فكلــه صحيــح جملـ ًة وتفصيــا ولكــن مــا ذكــره مــن‬\n      ‫أنــه حــل مــن أقســاط الســيارة املدعــى بهــا مبلــغ ســبعة آالف وخمســمائة‬\n      ‫ريــال فغيــر صحيــح بــل الصحيــح أن احلــال منهــا الــذي لــم يتــم ســداده‬\n      ‫هــو فقــط ثالثــة آالف ريــال حيــث أننــي قمــت قبــل حوالــي عشــرون يومـ ًا‬\n      ‫بالتحويــل إلــى حســاب هــذا املدعــي مــن قيمــة الســيارة املدعــى بهــا مبلــغ‬\n      ‫أربعــة آالف وخمســمائة ريــال هكــذا أجــاب وبعــرض مــا أجــاب بــه علــى‬\n      ‫املدعــي وســؤاله عنــه أجــاب بقولــه مــا ذكــره هــذا املدعــى عليــه مــن أنــه‬\n      ‫قــام بتحويــل مبلــغ أربعــة آالف وخمســمائة ريــال حلســابي فغيــر صحيــح‬\n      ‫وإذا كان لديــه إثبــات فأطلــب إحضــاره هكــذا أجــاب فســألت املدعــى‬\n      ‫عليــه هــل لديــه بينــة علــى صحــة مــا ذكــره مــن أنــه قــام بتحويــل مبلــغ‬\n      ‫أربعــة آالف وخمســمائة ريــال حلســاب املدعــي فأجــاب بقولــه نعــم لــدي‬\n      ‫ـاء‬\n        ‫البينــة علــى ذلــك وأطلــب إمهالــي يف إحضارهــا هكــذا أجــاب فبنـ ً‬\n      ‫عليــه ولالطــاع علــى بينــة املدعــى عليــه علــى ســداد املبلــغ الــذي ذكــره‬\n      ‫رفعــت اجللســة ويف يــوم االحــد املوافــق ‪1434/7/23‬ه ـ ويف املوعــد‬\n      ‫احملــدد افتتحــت اجللســة وفيهــا حضــر الطرفــان املدعــي واملدعــى عليــه‬\n      ‫ثــم ســألت املدعــي عــن رقــم حســابه لــدى مصــرف الراجحــي فأجــاب‬\n      ‫قائــا الرقــم هــو‪ 7/1362‬هكــذا أجــاب ثــم ســألت املدعــى عليــه عمــا‬\n      ‫وعــد بإحضــاره يف اجللســة املاضيــة فأبــرز كشــفا حلســابه لــدى مصــرف‬\n      ‫الراجحــي موضحــا فيــه أنــه مت بتاريخ‪1434/6/21‬ه ـ حتويــل مبلــغ ثالثة‬\n      ‫آالف ريــال مــن حســاب املدعــى عليــه ذي الرقــم ‪ ...........‬إلــى احلســاب رقم‬\n      ‫‪ 384001362‬وحتويــل ألــف وخمســمائة ريــال بتاريــخ ‪1434/6/25‬ه ـ‬\n\n\n‫‪253‬‬\n\f‫هــذا مــا أبــرزه املدعــى عليــه وبعرضــه علــى املدعــي صــادق عليــه ثــم‬\n‫قــرر قائــا إننــي اطلــب احلكــم بإلــزام املدعــى عليــه بســداد احلــال ممــا‬\n‫بذمــة مكفولــه وقــدره ثالثــة آلــف ريــال وااللتــزام بدفــع الباقــي وقــدره‬\n‫تســعة وعشــرون ألفــا وخمســمائة ريــال مقســطا حســب مــا ذكرتــه يف‬\n‫دعــواي ســابقا هكــذا قــرر‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى واالجابــة‬\n‫املتضمنــة مصادقــة املدعــى عليــه علــى مــا جــاء يف دعــوى املدعــي مــن‬\n‫البيــع والثمــن ومقــدار االقســاط والكفالــة وحيــث دفــع بانــه قــد ســدد‬\n‫للمدعــي مــن املبلــغ احلــال املدعــى بــه أربعــة آالف وخمســمائة ريــال وأبــرز‬\n‫بينــة علــى ذلــك ولكونــه يحــق للمدعــي املطالبــة بتســليم املبلــغ احلــال‬\n‫وااللتــزام بدفــع املؤجــل يف حينــه لثبوتــه يف الذمــة بالعقــد اســتنادا ملــا‬\n‫نصــت عليــه املــادة ‪ 3/147‬مــن نظــام املرافعــات الشــرعية ولوائحــه‬\n‫التنفيذيــة فقــد حكمــت علــى املدعــى عليــه بــأن يدفــع للمدعــي املبلــغ‬\n‫احلــال مــن قيمــة الســيارة املوصوفــة يف الدعــوى وقــدره ثالثــة آالف ريــال‬\n‫حــاال والزمتــه بدفــع الباقــي وقــدره تســعة وعشــرون ألفــا وخمســمائة‬\n‫ريــال يف أوقــات حلولهــا بواقــع ألــف وخمســمائة ريــال شــهريا حتــل يف‬\n‫اليــوم اخلامــس والعشــرين مــن كل شــهر وتبــدأ مــن ‪1434/7/25‬ه ـ‬\n‫وأفهمتــه بــأن لــه الرجــوع علــى مكفولــه مبــا يدفعــه عنــه متــى رغــب‬\n‫ذلــك هــذا مــا ظهــر لــي وبــه حكمــت وبإعــان احلكــم علــى الطرفــن‬\n‫قنــع بــه املدعــي أمــا املدعــى عليــه فقــد قــرر عــدم القناعــة وقــرر قائــا‬\n‫إننــي ال أســتطيع دفــع املبلــغ احملكــوم بــه لوجــود عــدة التزامــات علــي‬\n‫هكــذا قــرر وطلــب االســتئناف بالئحــة اعتراضيــة فأفهمتــه مبراجعــة‬\n‫احملكمــة يــوم غــد بــإذن اهلل الســاعة الواحــدة والنصــف ظهــرا الســتالم‬\n‫نســخة احلكــم وتقــدمي اعتراضــه عليــه خــال املــدة املقــررة لالعتــراض‬\n\n\n                                                                                      ‫‪254‬‬\n\f      ‫وهــي ثالثــون يومــا مــن تاريــخ االســتالم احملــدد فــإن لــم يقــدم اعتراضــه‬\n      ‫خاللهــا ســقط حقــه يف التمييــز واكتســب احلكــم الصفــة القطعيــة‬\n      ‫ففهــم ذلــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه‬\n                                              ‫وصحبــه حــرر يف ‪1434/7/23‬ه ـ ‪.‬‬\n\n\n\n      ‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 34234688‬وتاريــخ‬\n                                                      ‫‪1434/9/23‬هـ‪.‬‬\n\n\n\n\n‫‪255‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":250,"source_page_end":255,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f81522480908b572d4b0c219d8c6014c07b7257097b6d87e2f8160830190ee63","normalized_text_hash":"18be5581514cc6a8f85bdc59733fbd3e367ff4b847c384073184a549742906a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p250-34279834"},{"id":"bc6f7b7b-1746-5e28-8552-5ae504f17727","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع أرض زراعية -مطالبة بإثبات البيع واإلفراغ -صكوك ملكية العقار يستفسر عن سريان مفعولها من مصدرها -شهادة الشهود املعدلن -احلكم بثبوت بيع مورث املدعى عليهم للمدعي - التهميش على الصك بذلك بعد اكتساب احلكم للقطعية - رفع احلكم حملكمة الاستئناف لوجود قاصر .","document_number":"34330743","case_number":"34291219","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة اخلرج","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/14","year":"1434","subject":"بيع أرض زراعية -مطالبة بإثبات البيع واإلفراغ -صكوك ملكية العقار يستفسر عن سريان مفعولها من مصدرها -شهادة الشهود املعدلن -احلكم بثبوت بيع مورث املدعى عليهم للمدعي - التهميش على الصك بذلك بعد اكتساب احلكم للقطعية - رفع احلكم حملكمة الاستئناف لوجود قاصر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/10/14 :‬هـ‬\n                ‫ُ‬                  ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34330743 :‬‬\n                    ‫َر ْق ُم الدعوى‪34291219 :‬‬\n              ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 34361461:‬تاريخه‪1434/11/18 :‬هـ‬\n\n\n ‫بيــع أرض زراعيــة ‪ -‬مطالبــة بإثبــات البيــع واإلفــراغ ‪ -‬صكــوك ملكيــة‬\n ‫العقــار يستفســر عــن ســريان مفعولهــا مــن مصدرهــا ‪ -‬شــهادة الشــهود‬\n ‫املعدلــن ‪ -‬احلكــم بثبــوت بيــع مــورث املدعــى عليهــم للمدعــي ‪-‬‬\n ‫التهميــش علــى الصــك بذلــك بعــد اكتســاب احلكــم للقطعيــة ‪-‬‬\n                        ‫رفــع احلكــم حملكمــة االســتئناف لوجــود قاصــر ‪.‬‬\n\n\n\n\n                             ‫‪ .1‬املادة ‪ 179‬من نظام املرافعات الشرعية ‪.‬‬\n               ‫‪ .2‬تعميم وزير العدل رقم ‪/134/8‬ت وتاريخ ‪1420/8/21‬هـ ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه وكالــة بأنــه اشــترى موكلــه‬\n ‫مــن مــورث املدعــى عليهــم األرض الزراعيــة الواقعــة يف حــي ‪ ...‬مبحافظة‬\n ‫اخلــرج ومجمــوع مســاحتها اإلجماليــة قدرهــا خمســون ألفــا وأربعمائــة‬\n ‫دومن واململوكــة ملورثهــم مبوجــب الصــك الصــادر مــن كتابــة عــدل‬\n ‫اخلــرج بقيمــة قدرهــا مائة وخمســة وأربعون ألف ريالــ‪ 145000‬واملمنوحة‬\n ‫ملورثهــم مــن قبــل الدولــة ‪،‬وكان قــد اســتلم مــن مــوكل املدعــي كامــل‬\n ‫القيمــة واســتلم موكلــه األرض محــل الدعــوى ‪ ،‬وقــد تــويف مورثهــم قبــل‬\n ‫إفــراغ األرض ملوكلــه ويطلــب إثبــات هــذا البيــع وإلــزام املدعــى عليهــم‬\n\n                                                                                  ‫‪256‬‬\n\f      ‫أصالــة ووكالــة وواليــة بإفــراغ الصــك ملوكلــه هكــذا ادعــى ‪ ،‬أجــاب‬\n      ‫املدعــى عليــه باملصادقــة علــى الدعــوى واســتعداد موكليــه بإثبــات هــذا‬\n      ‫البيــع وإفــراغ األرض ملــوكل املدعــي هكــذا أجــاب ‪ ،‬ونظــرا لكــون‬\n      ‫األرض زراعيــة جــرى الكتابــة للبنــك الزراعــي مــن أجــل االستفســار‬\n      ‫عــن مــدى وجــود إلتزامــات ماليــة مــن عدمهــا علــى الصــك املذكــور‬\n      ‫فــورد اجلــواب بعــدم وجــود قــروض عليــه ‪ ،‬كمــا جــرى االستفســار عــن‬\n      ‫ســريان مفعــول الصــك مــن مصــدره كتابــة العــدل فــورد اجلواب بســريان‬\n      ‫مفعولــه ‪ ،‬أبــرز املدعــي وكالــة عقــد البيــع الــذي بــن موكلــه وبــن‬\n      ‫مــورث املدعــى عليهــم ‪ ،‬ونظــر ًا ملصادقــة املدعــى عليــه علــى مــا ورد يف‬\n      ‫دعــوى املدعــي وكالــة مــن بيــع مورثهــم األرض املذكــورة يف الدعــوى‬\n      ‫علــى املدعــي أصالــة بالقيمــة املذكــورة ‪ ،‬وبنــاء علــى العقــد املبــرم بــن‬\n      ‫ـاء علــى إفــادة البنــك الزراعــي بعــدم‬\n                                              ‫الطرفــن واملشــار إليــه ســابق ًا ‪ ،‬وبنـ ً‬\n      ‫وجــود إلتزامــات ماليــة علــى مــورث املدعــى عليهــم ‪ ،‬ونظــرا لكــون‬\n      ‫ـاء‬\n      ‫الصــك ســاري املفعــول وصالــح لإلعتمــاد عليــه عنــد اإلفــراغ ‪ ،‬وبنـ ً‬\n      ‫علــى املــادة ‪ 179‬مــن نظــام املرافعــات الشــرعية ‪ ،‬وبعــد االطــاع علــى‬\n      ‫تعميــم وزيــر العــدل رقــم ‪/134/8‬ت وتاريــخ ‪1420/8/21‬ه ـ ‪ ،‬ملــا تقــدم‬\n      ‫احلكــم بثبــوت بيــع مــورث املدعــى عليهــم لــأرض اململوكــة بالصــك‬\n      ‫الصــادر مــن كتابــة عــدل اخلــرج علــى املدعــي أصالــة بقيمــة اســتلمها‬\n      ‫مــورث املدعــى عليهــم ‪ ،‬والتهميــش علــى الصــك بذلــك بعــد اكتســاب‬\n      ‫احلكــم للقطعيــة ‪ ،‬صــدق احلكــم مــن الدائــرة احلقوقيــة الثانيــة‬\n                                                  ‫مبحكمــة االســتئناف بالريــاض ‪.‬‬\n\n\n\n\n‫‪257‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة اخلــرج وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة باخلــرج ‪ .....‬املكلــف برقــم ‪ 34291219‬وتاريــخ‬\n‫‪ 1434/06/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341531045‬وتاريــخ‬\n‫‪ 1434/06/25‬ه ـ ففــي يــوم األحــد املوافــق‪ 1434/06/25‬ه ـ فتحــت‬\n‫اجللســة الســاعة ‪ 10 : 15‬وفيهــا وفيهــا حضــر ‪.......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪.......‬الوكيــل عــن ‪.......‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪.......‬وذلــك مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 34264513‬وتاريــخ‬\n‫‪1434/3/3‬ه ـ واملجعــول فيهــا للوكيــل حــق شــراء األرض الصــادرة مــن‬\n‫كتابــة عــدل اخلــرج بحــي الشــديدة مــن البائــع ‪.......‬وقبــول االفــراغ ودفــع‬\n‫الثمــن واالســتالم والتســليم ومراجعــة جميــع اجلهــات احلكوميــة ذات‬\n‫العالقــة وإنهــاء جميــع االجــراءات الالزمــة لذلــك وادعــى علــى احلاضــر‬\n‫معــه يف املجلــس الشــرعي ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪.......‬باألصالــة عــن نفســه وبالواليــة علــى أخيــه ‪.......‬وذلــك مبوجــب‬\n‫صــك الواليــة الصــادر مــن احملكمــة العامــة بالريــاض برقــم‬\n‫‪ 17451486117731‬وتاريــخ ‪1431/12/18‬ه ـ وبالوكالــة عــن كل‬\n‫مــن ‪.......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬وذلــك‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض‬\n‫برقــم ‪ 3369972‬وتاريــخ ‪1433/5/11‬ه ـ واملجعــول فيهــا للوكيــل حــق‬\n‫املرافعــة واملدافعــة واالقــرار والصلــح واالبــراء والبيــع واالفــراغ‬\n\n                                                                                      ‫‪258‬‬\n\f      ‫وبالوكالــة عــن ‪.......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬‬\n      ‫وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــرق‬\n      ‫الريــاض برقــم ‪ 228575‬وتاريــخ ‪1431/12/25‬ه ـ واملجعــول فيهــا‬\n      ‫للوكيــل حــق ســماع الدعــاوى والــرد عليهــا والبيــع واالفــراغ وقبولــه‬\n      ‫واســتالم الثمــن وتســليم املثمــن وعــن كل مــن ‪.......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ....... .......‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪.......‬و‪ .......‬ســعودية اجلنســية مبوجــب الســجل املدني‬\n      ‫رقــم ‪.......‬و‪ .......‬ســعودية اجلنســية مبوجــب الســجل املدنــي ‪.......‬وذلــك‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بشــرق الريــاض‬\n      ‫برقــم ‪ 226619‬وتاريــخ ‪1431/12/21‬ه ـ واملجعــول فيهــا للوكيــل حــق‬\n      ‫املداعــاة واملخاصمــة وســماع الدعــاوى والــرد عليهــا والبيــع والشــراء‬\n      ‫واالفــراغ وقبولــه واســتالم الثمــن وتســليم املثمــن قائــا يف حتريــر دعــواه‬\n      ‫عليــه لقــد اشــترى موكلــي مــن مــورث املدعــى عليهــم ‪.......‬األرض‬\n      ‫الزراعيــة الواقعــة يف حــي ‪.......‬مبحافظــة اخلــرج ‪15‬كــم شــمال شــرق‬\n      ‫اخلــرج مــن تقاطــع ‪ ...‬وحدودهــا وأطوالهــا كالتالــي مــن الشــمال حــرم‬\n      ‫أبــراج الكهربــاء بعــرض ‪100‬م وبطــول ‪182‬م ومــن اجلنوب شــارع بعرض‬\n      ‫‪50‬م وبطــول ‪182‬م ومــن الشــرق القطعــة رقــم ‪ 45‬بطــول ‪277‬م ومــن‬\n      ‫الغــرب القطعــة رقــم ‪ 7‬بطــول ‪277‬م ومجمــوع مســاحتها االجماليــة‬\n      ‫قدرهــا خمســون ألفــا وأربعمائــة دومن واململوكــة ملورثهــم مبوجــب‬\n      ‫الصــك الصــادر مــن كتابــة عــدل اخلــرج برقــم ‪ 5/68/50‬وتاريــخ‬\n      ‫‪1434/2/20‬ه ـ بقيمــة قدرهــا مائة وخمســة وأربعون ألــف ريالـ‪145000‬‬\n      ‫وكان ذلــك بتاريــخ ‪1428/11/25‬ه ـ واملمنوحــة ملورثهــم مــن قبــل الدولة‬\n      ‫‪،‬وكان قــد اســتلم مــن موكلــي كامــل القيمــة واســتلم موكلــي‬\n\n\n‫‪259‬‬\n\f‫األرض محــل الدعــوى ‪ ،‬وقــد تــويف مورثهــم رحمــه اهلل قبل إفراغ األرض‬\n‫ملوكلــي لــذا أطلــب إثبــات هــذا البيــع وإلــزام املدعــى عليهــم أصالــة‬\n‫ووكالــة وواليــة بإفــراغ الصــك ملوكلــي هــذه دعــواي وأســأل املدعــى‬\n‫عليــه أصالــة وواليــة ووكالــة اجلــواب وبســؤال املدعــى عليــه عــن دعــوى‬\n‫املدعــي وكالــة أجــاب قائــا إن ماذكــره املدعــي وكالــة يف دعــواه‬\n‫كلــه صحيــح جملــة وتفصيــا فقــد اشــترى املدعــي أصالــة مــن مورثنــا‬\n‫والدنــا رحمــه اهلل األرض املذكــورة يف الدعــوى بالقيمــة املذكــورة‬\n‫وقــد اســتلم والــدي رحمــه اهلل القيمــة كاملــة وأنــا وموكلــي مســتعدون‬\n‫بإثبــات هــذا البيــع وإفــراغ األرض ملوكلــه هــذا مالــدي ونظــرا لكــون‬\n‫األرض زراعيــة فقــد قــررت الكتابــة للبنــك الزراعــي مــن أجــل‬\n‫االستفســار عــن مــدى وجــود التزامــات ماليــة مــن عدمهــا علــى الصــك‬\n‫املذكــور ‪ ،‬كمــا قــررت االستفســار عــن ســجله وســريان مفعولــه مــن‬\n‫كتابــة العــدل ‪ ،‬ثــم قــال املدعــي وكالــة لقــد أحضــرت معــي البينــة‬\n‫التــي تشــهد بالبيــع الــذي مت بــن موكلــي وبــن مــورث املدعــى عليهــم‬\n‫أطلــب ســماع مالديهــم مــن شــهادة لكونــه يصعــب علــي إحضارهــم مــرة‬\n‫أخــرى ألنهــم مــن مناطــق بعيــدة فأجبتــه لطلبــه فأحضــر كال مــن ‪.......‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬و‪.......‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪.......‬ولــدى ســؤالهما عمــا لديهمــا‬\n‫مــن شــهادة شــهد كل واحــد منهمــا مبفــرده قائــا أشــهد هلل تعالــى أن‬\n‫املدعــي أصالــة ‪.......‬قــد اشــترى مــن مــورث املدعــى عليهــم ‪.......‬بتاريــخ‬\n‫‪1428/11/25‬ه ـ األرض الزراعيــة الواقعــة بحــي ‪ ...‬مبحافظــة اخلــرج‬\n‫واململوكــة ملــورث املدعــى عليهــم مبوجــب الصــك الصــادر مــن كتابــة‬\n‫عــدل اخلــرج برقــم ‪ 5/68/50‬وتاريــخ ‪1434/2/20‬ه ـ وحدودهــا‬\n\n\n                                                                                    ‫‪260‬‬\n\f      ‫وأطوالهــا كالتالــي مــن الشــمال حــرم أبــراج الكهربــاء بعــرض ‪100‬م‬\n      ‫وبطــول ‪182‬م ومــن اجلنــوب شــارع بعــرض ‪50‬م وبطــول ‪182‬م ومــن‬\n      ‫الشــرق القطعــة رقــم ‪ 45‬بطــول ‪277‬م ومــن الغــرب القطعــة رقــم ‪ 7‬بطــول‬\n      ‫‪277‬م ومجمــوع مســاحتها االجماليــة قدرهــا خمســون ألفــا وأربعمائــة‬\n      ‫دومن بقيمــة قدرهــا مائــة وخمســة أربعــون ألــف ريالــ‪ 145000‬وقــد أقــر‬\n      ‫أمامنــا البائــع رحمــه اهلل باســتالمه لكامــل القيمــة وقــد ســلم األرض‬\n      ‫للمدعــي أصالــة هــذا مالــدي مــن شــهادة وعليــه أوقــع ‪ ،‬وبعــرض‬\n      ‫الشــاهدين وشــهادتهما علــى املدعــي عليــه أصالــة ووكالــة وواليــة قــال‬\n      ‫ال أقــول يف الشــاهدين إال خيــرا وشــهادتهما صحيحــة هــذا مالــدي ثــم‬\n      ‫جــرى تعديــل الشــهود مــن قبــل كال مــن ‪.......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪.......‬و ‪.......‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫رقــم ‪.......‬كمــا أبــرز املدعــي وكالــة العقد الصــادر مكتب ‪ ...‬العقاري‬\n      ‫برقــم ‪ 266‬وتاريــخ ‪1428/11/25‬ه ـ وباالطــاع عليــه وجــد يتضمــن بيــع‬\n      ‫مــورث املدعــى عليهــم ‪.......‬للمدعــي أصالــة ‪.......‬األرض الزراعيــة‬\n      ‫املذكــورة يف دعــوى املدعــي وكالــة علــى املدعــي أصالــة بقيمــة قدرهــا‬\n      ‫مائــة وخمســة وأربعــون ألــف ريالــ‪ 145000‬ويوجــد توقيــع منســوب ملــورث‬\n      ‫املدعــى عليهــم وشــهد علــى العقــد كال مــن ‪ .......‬و‪.......‬وبعرضــه علــى‬\n      ‫املدعــى عليــه أصالــة ووكالــة وواليــة صــادق عليــه وقــال التوقيــع‬\n      ‫املنســوب لوالــدي رحمــه اهلل صحيــح ‪ ،‬كمــا صــادق الشــاهدان علــى‬\n      ‫العقــد ‪ ،‬ثــم جــرى رفــع اجللســة مــن أجــل الكتابــة لكتابة العــدل والبنك‬\n      ‫الزراعــي ومــن أجــل إحضــار املدعــى عليــه لصــك حصــر ورثــة والــده‬\n      ‫وذلــك إلــى يــوم األحــد وتاريخ ‪1434/07/16‬هـ الســاعة ‪ 10 : 15‬صباح ًا‬\n      ‫ويف جلســة أخــرى حضــر الطرفــان ثــم أبــرز املدعــي وكالــة الوكالــة‬\n\n\n‫‪261‬‬\n\f‫الصــادرة مــن كتابــة عــدل محافظــة الدرعيــة برقــم ‪ 34822707‬وتاريــخ‬\n‫‪1434/6/26‬ه ـ وباالطــاع عليهــا وجــد أنهــا تتضمــن توكيــل ‪.......‬‬\n‫للمدعــي وكالــة وقــد جعــل فيهــا للوكيــل حــق املرافعــة واملدافعــة‬\n‫واإلقــرار واإلنــكار واالســتالم والتســليم ‪ ،‬كمــا جــرى االطــاع علــى‬\n‫صــك حصــر الورثــة الصــادر مــن احملكمــة العامــة بالريــاض برقــم ‪4/8‬‬\n‫وتاريــخ ‪1431/12/18‬ه ـ فوجــد يتضمــن ثبــوت وفــاة ‪.......‬بتاريــخ‬\n‫‪1431/11/29‬ه ـ وانحصــار إرثــه يف كل مــن زوجتــه ‪....... .......‬ويف‬\n‫أوالده البالغــن وهــم كال مــن ‪ ....... ....... ....... .......‬والقاصريــن ‪.......‬‬\n‫املولــودة ‪1418/1/23‬ه ـ ‪.......‬املولــود يف ‪1420/6/8‬ه ـ أوالد ‪،.......‬‬\n‫كمــا جــرى االطــاع علــى صــك الواليــة الصــادر مــن احملكمــة العامــة‬\n‫بالريــاض برقــم ‪ 174514861177310476‬وتاريــخ ‪1431/12/18‬ه ـ‬\n‫فوجــد يتضمــن أن احلاكــم الشــرعي قــد أقــام ‪.......‬وليــا علــى كل مــن‬\n‫‪ .....‬املولــودة يف ‪1418 /1/23‬ه ـ ‪ ...‬املولــود يف ‪1420/6/8‬ه ـ أوالد ‪.......‬‬\n‫وقــد همــش عليــه ببلــوغ ‪ ،.......‬وكان قــد جــرى منــا االطــاع علــى‬\n‫الصــك الصــادر مــن كتابــة عــدل اخلــرج برقــم ‪ 5/68/50‬وتاريــخ‬\n‫‪1434/2/20‬ه ـ فوجــد يتضمــن ملكيــة ‪.......‬لــأرض الواقعــة علــى بعــد‬\n‫‪15‬كــم شــمال شــرق اخلــرج مــن تقاطــع ‪ ...‬برقــم ‪ ...‬مــن املخطــط ‪ 201‬يف‬\n‫‪1417/4/21‬ه ـ وحدودهــا وأطوالهــا مــن الشــمال حرم أبــراج الكهرباء‬\n‫بعــرض ‪100‬م وبطــول ‪182‬م ومــن اجلنــوب شــارع بعــرض ‪50‬م وبطــول‬\n‫‪182‬م ومــن الشــرق القطعــة رقــم ‪ 45‬بطــول ‪277‬م ومــن الغــرب القطعــة‬\n‫رقــم ‪ 47‬بطــول ‪277‬م ومجمــوع مســاحتها االجماليــة خمســن ألفــا‬\n‫وأربعمائــة متــر مربــع (دومن) ‪50400‬م‪ 2‬فجــرى االستفســار عــن ســجله‬\n‫وســريان مفعولــه وذلــك مبوجــب خطابنــا رقــم ‪ 34/1141976‬وتاريــخ‬\n\n\n                                                                                      ‫‪262‬‬\n\f      ‫‪1434/5/8‬ه ـ املوجــه لرئيــس كتابــة عــدل اخلــرج فوردنــا شــرحه رقــم‬\n      ‫‪ 342026307‬وتاريــخ ‪1434/8/22‬ه ـ املتضمــن أن الصــك ســاري‬\n      ‫املفعــول ومطابــق لســجله حتــى تاريــخ االفــادة ‪ ،‬كمــا جــرت الكتابــة‬\n      ‫ملديــر فــرع صنــدوق التنميــة الزراعيــة مبحافظــة اخلــرج بالنيابــة مبوجــب‬\n      ‫خطابنــا رقــم ‪ 34/2298075‬وتاريــخ ‪1434/10/12‬ه ـ مــن أجــل االفــادة‬\n      ‫عــن الصــك رقــم ‪ 5/68/50‬وتاريــخ ‪1434/2/20‬ه ـ وهــل توجــد عليــه‬\n      ‫أي التزمــات ماليــة أم ال فوردنــا خطابــه رقــم ‪/5/2950‬أ وتاريــخ‬\n      ‫‪1434/10/13‬ه ـ املتضمــن أن األرض الزراعيــة املشــار إليهــا التوجــد‬\n      ‫عليهــا قــروض أو التزامــات أخــرى مســتحقة علــى البائــع جتــاه الصنــدوق‬\n      ‫حتــى تاريخــه ‪ ،‬ثــم جــرى ســؤال الطرفــن هــل لديهمــا مايضيفانــه فقــاال‬\n      ‫ليــس لدينــا مانضيفــه ‪ ،‬فبنــاء علــى ماتقــدم مــن الدعــوى واإلجابــة‬\n      ‫ونظــرا ملصادقــة املدعــى عليــه أصالــة ووكالــة وواليــة علــى مــاورد يف‬\n      ‫دعــوى املدعــي وكالــة مــن بيــع مورثهــم األرض املذكــورة يف الدعــوى‬\n      ‫علــى املدعــي أصالــة بالقيمــة املذكــورة ‪ ،‬وبنــاء علــى البينــة املعدلــة‬\n      ‫شــرعا التــي أحضرهــا املدعــي وكالــة ‪ ،‬وبنــاء علــى العقــد املبــرم بــن‬\n      ‫الطرفــن واملشــار إليــه ســابقا ‪ ،‬وبنــاء علــى إفــادة البنــك الزراعــي بعــدم‬\n      ‫وجــود التزامــات ماليــة علــى مــورث املدعــى عليهــم ‪ ،‬ونظــرا لكــون‬\n      ‫الصــك رقــم ‪ 5/68/50‬وتاريــخ ‪1434/2/20‬ه ـ ســار املفعــول وصالــح‬\n      ‫لالعتمــاد عليــه عنــد االفــراغ ‪ ،‬وبنــاء على املادة ‪ 179‬من نظام املرافعات‬\n      ‫الشــرعية ‪ ،‬وبعــد االطــاع علــى تعميــم وزيــر العــدل رقــم ‪/134/8‬ت‬\n      ‫وتاريــخ ‪1420/8/21‬ه ـ لــكل ماتقــدم فقــد ثبــت لدي بيــع مورث املدعى‬\n      ‫عليهــم لــأرض اململوكــة بالصــك الصــادر مــن كتابــة عــدل اخلــرج‬\n      ‫برقــم ‪ 5/68/50‬وتاريــخ ‪1434/2/20‬ه ـ بتاريــخ ‪1428/11/25‬ه ـ علــى‬\n\n\n‫‪263‬‬\n\f‫املدعــي أصالــة ‪.......‬بقيمــة قدرهــا مائــة وخمســة وأربعــون ألــف‬\n‫ريالــ‪ 145000‬اســتلمها مــورث املدعــى عليهــم ‪ ،‬ومباتقــدم حكمــت ‪،‬‬\n‫وقــررت التهميــش علــى الصــك الصــادر مــن كتابــة عــدل اخلــرج برقــم‬\n‫‪ 5/68/50‬وتاريــخ ‪1434/2/20‬ه ـ بذلــك بعــد اكتســاب احلكــم‬\n‫للقطعيــة ‪ ،‬وبعرضــه علــى الطرفــن قــررا القناعــة بــه وقــررت رفــع‬\n‫احلكــم حملكمــة االســتئناف حســب املتبــع وكان ختــام اجللســة يف‬\n‫الســاعة ‪ 10 : 30‬صباح ـ ًا ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمد وعلى آله وصحبه وسلم ‪ .‬حرر يف ‪ 1434/10/14‬هـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة اخلــرج برقــم‬\n‫‪ 341531045‬وتاريــخ ‪1434/10/26‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة القاضــي الشــيخ ‪ ........‬املســجل برقــم ‪ 34330743‬وتاريــخ‬\n‫‪1434/10/14‬ه ـ اخلــاص بدعــوى ‪ .......‬ضــد ‪ .......‬وبدارســة الصــك‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــرر الدائــرة أنــه لــم يظهــر مــا يوجــب‬\n‫املالحظــة ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪264‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":256,"source_page_end":264,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f4edeb1ebcaa9f71339926408ab030df07206b496418e8eb6d12ef5b6a1dfd31","normalized_text_hash":"c47c5d914684ddd8a3bd07b4e36d495fc33ef84adc6b9e300e86eb1a1c0c5a6d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p256-34330743"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

